package org.sleepwell.app;
import org.junit.Test;import java.time.*;import static org.junit.Assert.*;
public final class SnoozeUntilTest {
 static final long NOW=Instant.parse("2026-10-25T10:30:20Z").toEpochMilli();
 SnoozeUntil.State state(String run,String revision,int used,int base,boolean shorten,int limit,boolean enabled,boolean current,boolean focus,long wall,long elapsed,ZoneId zone){return new SnoozeUntil.State(run,revision,used,base,shorten,limit,enabled,current,focus,wall,elapsed,zone);}
 SnoozeUntil.State normal(){return state("run","r1",1,10,false,3,true,true,true,NOW,5000,ZoneOffset.UTC);}
 SnoozeUntil offer(){return new SnoozeUntil(normal());}
 @Test public void exactFutureClockDeadlinePreservesSecondsInsteadOfRoundingDelay(){assertEquals(Instant.parse("2026-10-25T10:35:00Z").toEpochMilli(),offer().resolve(635,normal()));assertEquals(280000,offer().resolve(635,normal())-NOW);}
 @Test public void pastEqualAndOutsideMaximumAreRejectedWithoutRollingTomorrow(){assertThrows(IllegalArgumentException.class,()->offer().resolve(630,normal()));assertThrows(IllegalArgumentException.class,()->offer().resolve(641,normal()));SnoozeUntil.State exact=state("run","r1",1,10,false,3,true,true,true,NOW-20000,5000,ZoneOffset.UTC);assertThrows(IllegalArgumentException.class,()->new SnoozeUntil(exact).resolve(630,exact));}
 @Test public void sixtyMinutesAndShrinkingLimitRemainBounded(){SnoozeUntil.State s=state("run","r1",2,9,true,5,true,true,true,NOW,5000,ZoneOffset.UTC);SnoozeUntil o=new SnoozeUntil(s);assertEquals(Instant.parse("2026-10-25T10:37:00Z").toEpochMilli(),o.resolve(637,s));assertThrows(IllegalArgumentException.class,()->o.resolve(638,s));SnoozeUntil.State max=state("run","r",0,60,false,5,true,true,true,NOW,5000,ZoneOffset.UTC);assertEquals(Instant.parse("2026-10-25T11:30:00Z").toEpochMilli(),new SnoozeUntil(max).resolve(690,max));}
 @Test public void changedOccurrenceCountSettingsAndRevisionCannotReuseAnOffer(){SnoozeUntil o=offer();for(SnoozeUntil.State s:new SnoozeUntil.State[]{state("new","r1",1,10,false,3,true,true,true,NOW,5000,ZoneOffset.UTC),state("run","r1",2,10,false,3,true,true,true,NOW,5000,ZoneOffset.UTC),state("run","r2",1,10,false,3,true,true,true,NOW,5000,ZoneOffset.UTC),state("run","r1",1,9,false,3,true,true,true,NOW,5000,ZoneOffset.UTC),state("run","r1",1,10,true,3,true,true,true,NOW,5000,ZoneOffset.UTC),state("run","r1",1,10,false,2,true,true,true,NOW,5000,ZoneOffset.UTC),state("run","r1",1,10,false,3,false,true,true,NOW,5000,ZoneOffset.UTC)})assertThrows(IllegalArgumentException.class,()->o.resolve(635,s));}
 @Test public void unavailableOwnerAndLostFocusCannotSchedule(){for(boolean current:new boolean[]{true,false})for(boolean focus:new boolean[]{true,false})if(!current||!focus){SnoozeUntil.State s=state("run","r1",1,10,false,3,true,current,focus,NOW,5000,ZoneOffset.UTC);assertThrows(IllegalArgumentException.class,()->offer().resolve(635,s));}}
 @Test public void wallClockJumpRollbackZoneChangeAndDateBoundaryRequireFreshReview(){for(SnoozeUntil.State s:new SnoozeUntil.State[]{state("run","r1",1,10,false,3,true,true,true,NOW+60000,6000,ZoneOffset.UTC),state("run","r1",1,10,false,3,true,true,true,NOW-60000,6000,ZoneOffset.UTC),state("run","r1",1,10,false,3,true,true,true,NOW,4000,ZoneOffset.UTC),state("run","r1",1,10,false,3,true,true,true,NOW,5000,ZoneId.of("Europe/London"))})assertThrows(IllegalArgumentException.class,()->offer().resolve(635,s));}
 @Test public void ordinaryElapsedTimeReducesTheRemainingExactDeadline(){SnoozeUntil.State later=state("run","r1",1,10,false,3,true,true,true,NOW+2000,7000,ZoneOffset.UTC);assertEquals(Instant.parse("2026-10-25T10:35:00Z").toEpochMilli(),offer().resolve(635,later));}
 @Test public void daylightGapAndOverlapCannotSilentlyChooseAnotherInstant(){ZoneId zone=ZoneId.of("America/New_York");long gap=Instant.parse("2026-03-08T06:45:00Z").toEpochMilli();SnoozeUntil.State g=state("run","r",0,60,false,2,true,true,true,gap,0,zone);assertThrows(IllegalArgumentException.class,()->new SnoozeUntil(g).resolve(135,g));assertEquals(Instant.parse("2026-03-08T07:05:00Z").toEpochMilli(),new SnoozeUntil(g).resolve(185,g));long overlap=Instant.parse("2026-11-01T04:50:00Z").toEpochMilli();SnoozeUntil.State f=state("run","r",0,60,false,2,true,true,true,overlap,0,zone);assertThrows(IllegalArgumentException.class,()->new SnoozeUntil(f).resolve(80,f));}
 @Test public void midnightNeverTurnsAnEarlierClockIntoTomorrow(){long now=Instant.parse("2026-10-25T23:58:20Z").toEpochMilli();SnoozeUntil.State s=state("run","r",0,10,false,2,true,true,true,now,0,ZoneOffset.UTC);assertThrows(IllegalArgumentException.class,()->new SnoozeUntil(s).resolve(5,s));assertEquals(Instant.parse("2026-10-25T23:59:00Z").toEpochMilli(),new SnoozeUntil(s).resolve(1439,s));}
 @Test public void cancellationAndSuccessfulConfirmationAreOneUseOnly(){SnoozeUntil o=offer();long[] deadline={0};SnoozeUntil.Port port=new SnoozeUntil.Port(){public SnoozeUntil.State state(){return normal();}public void schedule(long value){assertEquals(0,deadline[0]);deadline[0]=value;}};assertNull(o.confirm(635,port));assertTrue(o.completed());assertNotNull(o.confirm(635,port));assertEquals(Instant.parse("2026-10-25T10:35:00Z").toEpochMilli(),deadline[0]);SnoozeUntil cancelled=offer();cancelled.cancel();assertNotNull(cancelled.confirm(635,port));}
 @Test public void schedulerDenialIsAnExplicitErrorAndNeverBecomesCompleted(){SnoozeUntil o=offer();assertEquals("Exact timing denied",o.confirm(635,new SnoozeUntil.Port(){public SnoozeUntil.State state(){return normal();}public void schedule(long target){throw new SecurityException("Exact timing denied");}}));assertFalse(o.completed());}
 @Test public void disabledOrExhaustedOffersCannotBeCreated(){assertThrows(IllegalArgumentException.class,()->new SnoozeUntil(state("run","r",0,10,false,3,false,true,true,NOW,0,ZoneOffset.UTC)));assertThrows(IllegalArgumentException.class,()->new SnoozeUntil(state("run","r",3,10,false,3,true,true,true,NOW,0,ZoneOffset.UTC)));}
}
